1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const COMPONENT_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
4	  rune: 25,
5	  moonstone: 25,
6	};
7	const MAIN_ITEM_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	};
13	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
14	  ...MAIN_ITEM_BASE_PREMIUM_BY_TYPE,
15	  ...COMPONENT_BASE_PREMIUM_BY_TYPE,
16	};
17	const COMPONENT_BLOCK_SIZE = 3;
18	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
19	const CURSED_SURCHARGE_RATE = 0.5;
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
22	const LOYALTY_MINIMUM_YEARS = 2;
23	const LOYALTY_DISCOUNT_RATE = 0.2;
24	
25	type Item = {
26	  type: string;
27	  material?: string;
28	  enchantment?: number;
29	  cursed?: boolean;
30	};
31	
32	type Step = {
33	  op: string;
34	  items: Item[];
35	};
36	
37	type Scenario = {
38	  customer: { yearsWithMHPCO: number };
39	  steps: Step[];
40	};
41	
42	type QuoteResult = {
43	  premium: number;
44	};
45	
46	type ScenarioOutput = {
47	  results: QuoteResult[];
48	};
49	
50	const isComponent = (item: Item): boolean =>
51	  item.type in COMPONENT_BASE_PREMIUM_BY_TYPE;
52	
53	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
54	  sameTypeItems.length === COMPONENT_BLOCK_SIZE &&
55	  sameTypeItems.every(isComponent);
56	
57	const groupByType = (items: Item[]): Item[][] => {
58	  const groups = new Map<string, Item[]>();
59	  for (const item of items) {
60	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
61	  }
62	  return [...groups.values()];
63	};
64	
65	const basePremiumForItem = (item: Item): number =>
66	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
67	
68	const basePremiumForGroup = (sameTypeItems: Item[]): number => {
69	  if (isComponentBlock(sameTypeItems)) return COMPONENT_BLOCK_BASE_PREMIUM;
70	  return sameTypeItems.reduce(
71	    (total, item) => total + basePremiumForItem(item),
72	    0,
73	  );
74	};
75	
76	const basePremiumForItems = (items: Item[]): number =>
77	  groupByType(items).reduce(
78	    (total, group) => total + basePremiumForGroup(group),
79	    0,
80	  );
81	
82	const cursedSurcharge = (item: Item): number =>
83	  item.cursed ? basePremiumForItem(item) * CURSED_SURCHARGE_RATE : 0;
84	
85	const hasHighEnchantment = (item: Item): boolean =>
86	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
87	
88	const highEnchantmentSurcharge = (item: Item): number =>
89	  hasHighEnchantment(item)
90	    ? basePremiumForItem(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
91	    : 0;
92	
93	const totalItemSurcharges = (items: Item[]): number =>
94	  items.reduce(
95	    (total, item) =>
96	      total + cursedSurcharge(item) + highEnchantmentSurcharge(item),
97	    0,
98	  );
99	
100	const firstInsuranceSurcharge = (basePremium: number): number =>
101	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
102	
103	const loyaltyDiscount = (basePremium: number, yearsWithMHPCO: number): number =>
104	  yearsWithMHPCO >= LOYALTY_MINIMUM_YEARS
105	    ? basePremium * LOYALTY_DISCOUNT_RATE
106	    : 0;
107	
108	const premiumBeforeProcessingFee = (
109	  items: Item[],
110	  yearsWithMHPCO: number,
111	): number => {
112	  const basePremium = basePremiumForItems(items);
113	  return (
114	    basePremium +
115	    totalItemSurcharges(items) +
116	    firstInsuranceSurcharge(basePremium) -
117	    loyaltyDiscount(basePremium, yearsWithMHPCO)
118	  );
119	};
120	
121	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
122	  results: scenario.steps.map((step) => ({
123	    premium: Math.ceil(
124	      premiumBeforeProcessingFee(step.items, scenario.customer.yearsWithMHPCO) +
125	        PROCESSING_FEE,
126	    ),
127	  })),
128	});
